set-variable.value:
@{
            JObject body;
            try
            {
                body = context.Request.Body.As<JObject>(preserveContent: true);
            }
            catch
            {
                return "Request body must be JSON with to, subject, and body.";
            }
            if (body == null)
            {
                return "Request body must be JSON with to, subject, and body.";
            }
            var toToken = body["to"];
            var subjectToken = body["subject"];
            var bodyToken = body["body"];
            var to = (toToken != null && toToken.Type == JTokenType.String) ? toToken.ToString().Trim() : "";
            var subject = (subjectToken != null && subjectToken.Type == JTokenType.String) ? subjectToken.ToString().Trim() : "";
            var text = (bodyToken != null && bodyToken.Type == JTokenType.String) ? bodyToken.ToString().Trim() : "";
            if (string.IsNullOrWhiteSpace(to) || string.IsNullOrWhiteSpace(subject) || string.IsNullOrWhiteSpace(text))
            {
                return "Request body must include to, subject, and body.";
            }
            if (!System.Text.RegularExpressions.Regex.IsMatch(to, @"^[^@\s]+@[^@\s]+\.[^@\s]+$"))
            {
                return "to must be a well-formed email address.";
            }
            return "";
        }
